 const printed=engine.material(new T.MeshStandardMaterial({map:atlas,roughness:.86})),plastic=engine.material(new T.MeshPhysicalMaterial({map:atlas,roughness:.4,clearcoat:.2,clearcoatRoughness:.32})),teal=material(engine,'#2795a7'),purple=material(engine,'#c94bc6'),yellow=material(engine,'#f2d514',.24),card=engine.material(new T.MeshStandardMaterial({color:'#3c9dac',roughness:.94})),edge=engine.material(new T.MeshStandardMaterial({color:'#ae9873',roughness:1}));
