 const c=document.createElement('canvas');c.width=atlas.image.width;c.height=atlas.image.height;const ctx=c.getContext('2d');ctx.drawImage(atlas.image,0,0);const fill=pts=>{ctx.beginPath();pts.forEach(([u,v],i)=>i?ctx.lineTo(u*c.width,v*c.height):ctx.moveTo(u*c.width,v*c.height));ctx.closePath();ctx.fillStyle='#3e6268';ctx.fill();};fill(gunOutline);fill(leverOutline);for(const [u,v,w,h] of [[.13,.53,.22,.32],[.37,.51,.21,.34],[.56,.55,.25,.32]])ctx.fillRect(u*c.width,v*c.height,w*c.width,h*c.height);const backingTexture=new T.CanvasTexture(c);backingTexture.colorSpace=T.SRGBColorSpace;backingTexture.anisotropy=atlas.anisotropy;const backing=engine.material(new T.MeshStandardMaterial({map:backingTexture,roughness:.95}));backing.userData.ownedTexture=backingTexture;
 const add=(mesh,name)=>{mesh.name=name;group.add(mesh);return mesh;};
 const cardShape=polygon([[.015,.015],[.98,.015],[1,.05],[1,1],[0,1],[0,.05]]),cardGeo=new T.ExtrudeGeometry(cardShape,{depth:.008,bevelEnabled:true,bevelSize:.002,bevelThickness:.002,bevelSegments:1,steps:1});cardGeo.translate(0,0,-PACK.depth/2);add(projectedMesh(engine,cardGeo,backing,card),'Printed backing card');
